contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(deposit > 0, "deposit must be positive");
        require(address(this).balance >= deposit, "insufficient balance");

        c.addToBalance{value: deposit}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;

        assert(balAfter == 0 && ethAfter <= ethBefore);
    }

    receive() external payable {}
}

