pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit, uint256 withdrawAmount) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit > 0);
        vm.assume(address(this).balance >= deposit);
        try c.addToBalance{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.withdrawBalance() {} catch { return; }
        uint256 balAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        assertTrue(balAfter == 0 && ethAfter <= ethBefore);
    }

    function testFuzz_run(uint256 deposit, uint256 withdrawAmount) public {
        _run(deposit, withdrawAmount);
    }

    receive() external payable {}
}
